mapper.select:
SELECT a.id, a.category_id, c.name AS category_name, a.title, a.author, a.cover, a.introduction, a.sort_order, a.status, a.recommend_hot, a.recommend_banner, a.browse_count, a.spu_id, a.is_deleted, a.create_time, a.update_time FROM promotion_article a LEFT JOIN promotion_article_category c ON c.id = a.category_id WHERE a.is_deleted = 0 AND a.status = 1
AND a.recommend_hot = #{recommendHot}
AND a.recommend_banner = #{recommendBanner}
ORDER BY a.sort_order ASC, a.id DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM promotion_article
WHERE title = #{title}

    AND id != #{excludeId}

mapper.update:
UPDATE promotion_article
SET status = #{status}, update_time = #{updateTime}
WHERE id = #{id} AND is_deleted = 0

